package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.annotation.JsonAutoDetect;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.jsontype.TypeSerializer;
import com.fasterxml.jackson.databind.node.JsonNodeFactory;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class ObjectNode_setAll_TriageGen1Test {

    private JsonNodeFactory factory;
    private ObjectNode objectNode;

    @Before
    public void setUp() {
        factory = JsonNodeFactory.instance;
        objectNode = factory.objectNode();
    }

    @Test
    public void testSetAllWithValidProperties() {
        Map<String, JsonNode> properties = new HashMap<>();
        properties.put("key1", factory.textNode("value1"));
        properties.put("key2", factory.numberNode(123));

        JsonNode result = objectNode.setAll(properties);

        // Verify return type and fluent API
        assertSame(objectNode, result);

        // Verify contents
        assertEquals(2, objectNode.size());
        assertEquals("value1", objectNode.get("key1").asText());
        assertEquals(123, objectNode.get("key2").asInt());
    }

    @Test
    public void testSetAllWithNullValues() {
        Map<String, JsonNode> properties = new HashMap<>();
        properties.put("nullKey", null);
        properties.put("validKey", factory.booleanNode(true));

        objectNode.setAll(properties);

        // Verify that null in map is converted to NullNode per implementation logic
        assertTrue(objectNode.has("nullKey"));
        assertTrue(objectNode.get("nullKey").isNull());
        assertTrue(objectNode.get("validKey").isBoolean());
        assertEquals(2, objectNode.size());
    }

    @Test
    public void testSetAllOverwritesExistingKeys() {
        // Pre-populate
        objectNode.put("existing", factory.textNode("old"));

        Map<String, JsonNode> properties = new HashMap<>();
        properties.put("existing", factory.textNode("new"));
        properties.put("newKey", factory.textNode("added"));

        objectNode.setAll(properties);

        assertEquals(2, objectNode.size());
        assertEquals("new", objectNode.get("existing").asText());
        assertEquals("added", objectNode.get("newKey").asText());
    }

    @Test
    public void testSetAllWithEmptyMap() {
        Map<String, JsonNode> properties = new HashMap<>();

        int initialSize = objectNode.size();
        JsonNode result = objectNode.setAll(properties);

        assertSame(objectNode, result);
        assertEquals(initialSize, objectNode.size());
    }

    @Test
    public void testSetAllWithMixedTypes() {
        Map<String, JsonNode> properties = new HashMap<>();
        properties.put("str", factory.textNode("s"));
        properties.put("int", factory.numberNode(1));
        properties.put("bool", factory.booleanNode(false));
        properties.put("obj", factory.objectNode());
        properties.put("arr", factory.arrayNode());
        properties.put("nullVal", null);

        objectNode.setAll(properties);

        assertEquals(6, objectNode.size());
        assertTrue(objectNode.get("str").isTextual());
        assertTrue(objectNode.get("int").isNumber());
        assertTrue(objectNode.get("bool").isBoolean());
        assertTrue(objectNode.get("obj").isObject());
        assertTrue(objectNode.get("arr").isArray());
        assertTrue(objectNode.get("nullVal").isNull());
    }
}
